        evt.SetDoorState(5, DoorAction.Open)
        evt.SetDoorState(6, DoorAction.Open)
        XeenQuests.hook("m23.vault_door")
        return
    end
    if continueStep ~= nil then
        evt.StatusText("Incorrect! The door hums a little louder. Nothing else happens.", 6)
        return
    end
    if not (not (IsQBitSet(QBit(111461)))) then
        XeenQuests.hook("m23.vault_door")
        return
    end
    evt.AskQuestion(38, 1, 0, 2, "What is the password?", {"laboratory"})
end, "Vault door")

